def maxProfitFewestTrades(prices):
    profit = 0
    trades = 0
    in_trade = False
    for i in range(1, len(prices)):
        d = prices[i] - prices[i - 1]
        if d < 0:
            in_trade = False
        elif d > 0:
            profit += d
            if not in_trade:
                trades += 1
                in_trade = True
    return [profit, trades]
